     2| * api_deepseek.js — DeepSeek API 封装
     3| *
     4| * 使用方式：
     5| *   const api = new DeepSeekAPI('your-api-key');
     6| *   const result = await api.chat([{role:'user', content:'...'}]);
     7| */
     8|
     9|class DeepSeekAPI {
    10|  constructor(apiKey) {
    11|    this.apiKey = apiKey;
    12|    this.baseURL = "https://api.deepseek.com/v1";
    13|    this.model = "deepseek-chat"; // 或 "deepseek-coder" 用于代码推理
    14|    this.defaultOptions = {
    15|      temperature: 0.7,
    16|      max_tokens: 800,
    17|    };
    18|  }
    19|
    20|  /**
    21|   * 通用聊天接口
    22|   * @param {Array} messages - [{role: 'system'|'user'|'assistant', content: string}]
    23|   * @param {Object} options - { temperature?, max_tokens?, model? }
    24|   * @returns {Promise<string>} assistant 回复文本
    25|   */
    26|  async chat(messages, options = {}) {
    27|    const merged = { ...this.defaultOptions, ...options };
    28|    const response = await fetch(`${this.baseURL}/chat/completions`, {
    29|      method: "POST",
    30|      headers: {
    31|        "Content-Type": "application/json",
    32|        "Authorization": `Bearer ${this.apiKey}`,
    33|      },
    34|      body: JSON.stringify({
    35|        model: merged.model || this.model,
    36|        messages,
    37|        temperature: merged.temperature,
    38|        max_tokens: merged.max_tokens,
    39|      }),
    40|    });
    41|
    42|    if (!response.ok) {
    43|      const err = await response.text();
    44|      throw new Error(`DeepSeek API error ${response.status}: ${err}`);
    45|    }
    46|
    47|    const data = await response.json();
    48|    return data.choices[0].message.content.trim();
    49|  }
