     2|  const STORAGE_KEY = "oriental_destiny_reading_state";
     3|
     4|  function read() {
     5|    try {
     6|      const raw = window.localStorage.getItem(STORAGE_KEY);
     7|      return raw ? JSON.parse(raw) : {};
     8|    } catch {
     9|      return {};
    10|    }
    11|  }
    12|
    13|  function write(data) {
    14|    try {
    15|      window.localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
    16|    } catch {
    17|      // Ignore storage issues in static preview mode.
    18|    }
    19|  }
    20|
    21|  function merge(data) {
    22|    const next = { ...read(), ...data };
    23|    write(next);
    24|    return next;
    25|  }
    26|
    27|  function fromQuery() {
    28|    const params = new URLSearchParams(window.location.search);
    29|    const data = {};
    30|    ["focus", "full_name", "birth_date", "birth_time", "notes", "carrier"].forEach((key) => {
    31|      const value = params.get(key);
    32|      if (value) data[key] = value;
    33|    });
    34|    return data;
    35|  }
    36|
    37|  function toQuery(data) {
    38|    const params = new URLSearchParams();
    39|    Object.entries(data).forEach(([key, value]) => {
    40|      if (value) params.set(key, value);
    41|    });
    42|    return params.toString();
    43|  }
    44|
    45|  window.ReadingState = {
    46|    read,
    47|    write,
    48|    merge,
    49|    fromQuery,
    50|    toQuery
    51|  };
    52|})();
