   673|        function getKuaNumber(year, gender) {
   674|            let sum = year % 100;
   675|            sum = Math.floor(sum / 10) + (sum % 10);
   676|            while (sum >= 10) {
   677|                sum = Math.floor(sum / 10) + (sum % 10);
   678|            }
   679|            
   680|            let kua;
   681|            if (year >= 2000) {
   682|                kua = gender === 'male' ? (9 - sum) : (6 + sum);
   683|            } else {
   684|                kua = gender === 'male' ? (10 - sum) : (5 + sum);
   685|            }
   686|            
   687|            while (kua >= 10) {
   688|                kua = Math.floor(kua / 10) + (kua % 10);
   689|            }
   690|            if (kua === 0) kua = 9;
   691|            if (kua === 5) kua = gender === 'male' ? 2 : 8;
   692|            
   693|            return kua;
   694|        }
