        function calculateElement() {
            const yearVal = parseInt(document.getElementById('birthYear').value);
            if (!yearVal) {
                alert('Please enter or confirm your birth year.');
                return;
            }

            const stem = getYearHeavenlyStem(yearVal);
            const branch = getYearEarthlyBranch(yearVal);
            const element = getElementFromStem(stem);
            const animal = zodiacAnimals[(yearVal - 4) % 12];
            const data = elementData[element];

            // Build query params for upsell link
            const carriedState = (window.ReadingState && window.ReadingState.read()) || {};
            const params = new URLSearchParams({
                birth_date: `${yearVal}-01-01`,
                focus: carriedState.focus || 'balance',
                full_name: carriedState.full_name || '',
                notes: carriedState.notes || ''
            });
            document.getElementById('upsellLink').href = `checkout.html?${params.toString()}`;

            // Element badge
            const badge = document.getElementById('elementBadge');
            badge.className = 'element-badge ' + element.toLowerCase();
            document.getElementById('elementSymbol').textContent = data.symbol;
            document.getElementById('elementLabel').textContent = element;

            // Title
            document.getElementById('resultTitle').textContent = `${animal} Year — ${element} Element`;
            document.getElementById('resultSubtitle').textContent = `${stem} / ${branch} — energetic signature of your birth year`;

            // Zodiac tag
            document.getElementById('zodiacTag').textContent = `Year of the ${animal}`;

            // Traits
            document.getElementById('traitsGrid').innerHTML = data.traits.map(t => `
                <div class="trait-card">
                    <div class="trait-icon">${t.icon}</div>
                    <div class="trait-label">${t.label}</div>
                    <div class="trait-value">${t.value}</div>
                </div>
            `).join('');

            // Description
            const desc = document.getElementById('elementDesc');
            desc.className = 'element-desc ' + element.toLowerCase();
            document.getElementById('descTitle').textContent = data.descTitle;
            document.getElementById('descBody').textContent = data.descBody;
            document.getElementById('descExtra').textContent = data.descExtra;

            // Direction pills
            const pillHtml = data.supportive.map(d => `<span class="direction-pill supportive">↑ ${d}</span>`).join('') +
                             data.challenging.map(d => `<span class="direction-pill challenging">↓ ${d}</span>`).join('');
            document.getElementById('directionPills').innerHTML = pillHtml;

            document.getElementById('inputSection').style.display = 'none';
            document.getElementById('resultsSection').style.display = 'block';
            window.scrollTo({ top: 0, behavior: 'smooth' });
        }

        function resetForm() {
            document.getElementById('resultsSection').style.display = 'none';
            document.getElementById('inputSection').style.display = 'block';
            document.getElementById('birthDate').value = '';
            document.getElementById('birthYear').value = '';
            document.getElementById('zodiacNote').textContent = 'Your zodiac sign will appear here';
            window.scrollTo({ top: 0, behavior: 'smooth' });
        }
    </script>
    <script src="reading_state.js"></script>
</body>
